/*
 * [演算法說明]
 * 這是一個典型的動態規劃 (Dynamic Programming) 問題。
 * 給定一個整數序列和一個除數 K，判斷是否能在數字之間加上 '+' 或 '-'，使得最後的結果能被 K 整除。
 * 
 * 狀態定義：
 * dp[i][j] 表示使用前 i 個數字，是否能得到餘數為 j 的和 (0 <= j < K)。
 * 
 * 轉移方程：
 * 如果 dp[i-1][j] 為真，那麼：
 * dp[i][(j + abs(nums[i])) % K] = true
 * dp[i][(j - abs(nums[i]) % K + K) % K] = true
 * 
 * 空間優化：
 * 由於 dp[i] 只依賴於 dp[i-1]，我們可以使用滾動陣列將空間複雜度從 O(N*K) 降低到 O(K)。
 */

#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

void solve() {
    int N, K;
    if (!(cin >> N >> K)) return;

    vector<int> nums(N);
    for (int i = 0; i < N; ++i) {
        cin >> nums[i];
    }

    vector<bool> dp(K, false);
    // 第一個數字的餘數作為初始狀態
    dp[abs(nums[0]) % K] = true;

    for (int i = 1; i < N; ++i) {
        vector<bool> next_dp(K, false);
        int val = abs(nums[i]) % K;
        for (int j = 0; j < K; ++j) {
            if (dp[j]) {
                next_dp[(j + val) % K] = true;
                next_dp[(j - val % K + K) % K] = true;
            }
        }
        dp = next_dp;
    }

    if (dp[0]) cout << "Divisible" << endl;
    else cout << "Not divisible" << endl;
}

int main() {
    int M;
    if (cin >> M) {
        while (M--) {
            solve();
        }
    }
    return 0;
}
